// 三種報名身份對照：畫面顯示文字 + LINE通知/訊息開頭標籤
const TYPE_LABELS = {
  '個人': { title: '個人報名', notice: '新報名通知' },
  '企業': { title: '企業報名', notice: '企業報名通知' },
  '設攤': { title: '現場設攤', notice: '設攤通知' }
};
let currentRegType = '個人';

function showTypeModal(){
  document.getElementById('typeModal').classList.add('show');
}
function hideTypeModal(){
  document.getElementById('typeModal').classList.remove('show');
}
function selectRegType(type){
  currentRegType = type;
  hideTypeModal();
  showRegisterModal();
}

function showRegisterModal(){
  const info = TYPE_LABELS[currentRegType] || TYPE_LABELS['個人'];
  document.getElementById('registerModalTitle').textContent = '報名 AI 微型論壇 · ' + info.title;
  const m = document.getElementById('registerModal');
  m.classList.add('show');
  document.getElementById('registerForm').reset();
}
function hideRegisterModal(){
  document.getElementById('registerModal').classList.remove('show');
}
function showSuccessModal(){
  document.getElementById('successModal').classList.add('show');
}
function hideSuccessModal(){
  document.getElementById('successModal').classList.remove('show');
}

let lastRegistration = null;
function submitRegistration(e){
  e.preventDefault();
  const name = document.getElementById('regName').value.trim();
  const phone = document.getElementById('regPhone').value.trim();
  const email = document.getElementById('regEmail').value.trim();
  const company = document.getElementById('regCompany').value.trim();
  const taxId = document.getElementById('regTaxId').value.trim();
  if(!name || !phone){ alert('請完整填寫姓名與聯絡電話'); return; }
  const info = TYPE_LABELS[currentRegType] || TYPE_LABELS['個人'];
  lastRegistration = { name, phone, email, company, taxId, type: currentRegType };
  fetch('https://sme-register-fn.netlify.app/.netlify/functions/register', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    // session 欄位加上【XX通知】前綴：若後端把session原樣顯示在通知裡，這裡就能反映身份差異
    body: JSON.stringify({ session: '【' + info.notice + '】' + SESSION_NAME, name, company, taxId, phone, email, type: currentRegType })
  }).catch(()=>{});
  fetch(BYMYWAY_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ slug: BYMYWAY_SLUG, name, phone, company, email })
  }).catch(()=>{});
  const form = e.target;
  const submitBtn = form.querySelector('button[type="submit"]');
  const origText = submitBtn.innerHTML;
  submitBtn.disabled = true;
  submitBtn.innerHTML = '處理中...';
  setTimeout(() => {
    hideRegisterModal();
    showSuccessModal();
    submitBtn.disabled = false;
    submitBtn.innerHTML = origText;

