with urllib.request.urlopen(req, timeout=10) as resp:
    data = json.loads(resp.read().decode())
chats = {}
for u in data.get('result', []):
    for key in ['message','my_chat_member','channel_post','edited_message']:
        if key in u:
            chat = u[key].get('chat', {})
            cid = chat.get('id')
            if cid:
                chats[cid] = {'title': chat.get('title'), 'type': chat.get('type'), 'username': chat.get('username')}
print('已知chat清單:')
for cid, info in chats.items():
    print(cid, info)
print('---原始updates筆數---', len(data.get('result', [])))
"

